#include <bits/stdc++.h>
using namespace std;using U=uint32_t;using Clock=chrono::steady_clock;
const int Q=29;int inv[Q];int mod(int x){x%=Q;return x<0?x+Q:x;}int dec(char c){return c<='9'?c-'0':c-'a'+10;}char enc(int x){return x<10?'0'+x:'a'+x-10;}
vector<pair<string,int>> dict;
struct Var{int track,idx,skip,len;string truth;vector<string> words;vector<int> fac;};
struct Site{int v,i;};struct Fac{int start,n;array<int,3>v,off;vector<array<int,3>> c;};
struct Graph{vector<Var> vars;vector<Fac> fac;array<vector<Site>,3> sites;array<vector<int>,3> c,plain;};
Graph make_graph(array<vector<string>,3>&words,int ix){Graph g;for(int k=0;k<3;k++){int skip=-76;for(auto&w:words[k])skip+=w.size();for(int wi=0;wi<(int)words[k].size();wi++){auto&w=words[k][wi];if(skip>=(int)w.size()){skip-=w.size();continue;}Var v{k,wi,skip,(int)w.size(),w.substr(skip),{}, {}};map<string,int> ds;if(ix==2&&k==2&&wi==0&&w.size()==1){for(int j=0;j<29;j++)ds[string(1,enc(j))]=1;}else for(auto&[s,f]:dict)if(s.size()==w.size()){string p=s.substr(skip);ds[p]=max(ds[p],f);}vector<pair<int,string>> temp;for(auto&[s,f]:ds)temp.push_back({-f,s});sort(temp.begin(),temp.end());for(auto&[f,s]:temp)v.words.push_back(s);int vi=g.vars.size();for(int j=0;j<(int)v.truth.size();j++){g.sites[k].push_back({vi,j});g.plain[k].push_back(dec(v.truth[j]));}g.vars.push_back(move(v));skip=0;}if(g.plain[k].size()!=76)throw runtime_error("length");for(int j=0;j<76;j++){int a=1+(7*j*j+11*j+3+ix*9)%28,b=(13*j*j+5*j+17+ix*7)%29;g.c[k].push_back(ix==2?g.plain[k][j]:mod(a*g.plain[k][j]+b));}}
 for(int j=0;j<76;j++){array<int,3>v,off,c;for(int k=0;k<3;k++){v[k]=g.sites[k][j].v;off[k]=g.sites[k][j].i;c[k]=g.c[k][j];}if(!g.fac.empty()&&g.fac.back().v==v){g.fac.back().n++;g.fac.back().c.push_back(c);}else{int fi=g.fac.size();g.fac.push_back({j,1,v,off,{c}});for(int k=0;k<3;k++)g.vars[v[k]].fac.push_back(fi);}}
 return g;
}
using Dom=vector<vector<int>>;
U projection(const string&s,int off,int n){U p=0;for(int j=0;j<n;j++)p|=U(dec(s[off+j]))<<(5*j);return p;}
struct Solver{Graph &g;Clock::time_point begin=Clock::now();int ms;uint64_t pairs=0,facCalls=0,visits=0,branches=0;bool timeout=false;int maxVisits;int mode=0;vector<Dom> sol;int contradiction=-1;
 bool timed(){if(chrono::duration_cast<chrono::milliseconds>(Clock::now()-begin).count()>ms){timeout=true;return true;}return false;}
 bool factor(Dom&D,int fi,vector<int>&changed){auto&f=g.fac[fi];int n=f.n;array<vector<U>,3>P;array<unordered_set<U>,3>S;for(int k=0;k<3;k++){int v=f.v[k];for(int w:D[v])P[k].push_back(projection(g.vars[v].words[w],f.off[k],n));sort(P[k].begin(),P[k].end());P[k].erase(unique(P[k].begin(),P[k].end()),P[k].end());if(P[k].empty())return false;}
 int a=0,b=1,z=2;uint64_t best=UINT64_MAX;for(int x=0;x<3;x++)for(int y=x+1;y<3;y++){int d=3-x-y,wild=0;for(auto&c:f.c)wild+=c[x]==c[y]&&c[x]!=c[d];uint64_t cost=uint64_t(P[x].size())*P[y].size()*(10+wild*3);if(cost<best){best=cost;a=x;b=y;z=d;}}
 U fixed=0;vector<int> r(n),eq(n),free(n);for(int j=0;j<n;j++){auto c=f.c[j];eq[j]=c[a]==c[b];free[j]=eq[j]&&c[a]!=c[z];if(!free[j])fixed|=31u<<(5*j);r[j]=eq[j]?0:mod((c[z]-c[a])*inv[mod(c[b]-c[a])]);}
 unordered_map<U,vector<U>> lookup;lookup.reserve(P[z].size());for(U p:P[z])lookup[p&fixed].push_back(p);
 bool all=false;for(U x:P[a]){for(U y:P[b]){pairs++;if((pairs&65535)==0&&timed())return false;bool ok=true;U t=0;for(int j=0;j<n;j++){int X=(x>>(5*j))&31,Y=(y>>(5*j))&31;if((X==Y)!=bool(eq[j])){ok=false;break;}if(!free[j])t|=U(mod(X+r[j]*(Y-X)))<<(5*j);}if(!ok)continue;auto it=lookup.find(t);if(it==lookup.end())continue;for(U p:it->second){bool good=true;for(int j=0;j<n;j++)if(free[j]&&((p>>(5*j))&31)==((x>>(5*j))&31)){good=false;break;}if(good){S[a].insert(x);S[b].insert(y);S[z].insert(p);}}if(S[0].size()==P[0].size()&&S[1].size()==P[1].size()&&S[2].size()==P[2].size()){all=true;break;}}if(all)break;}
 facCalls++;if(all)return true;for(int k=0;k<3;k++){int v=f.v[k];auto&d=D[v];size_t old=d.size();d.erase(remove_if(d.begin(),d.end(),[&](int w){return !S[k].count(projection(g.vars[v].words[w],f.off[k],n));}),d.end());if(d.empty()){contradiction=fi;return false;}if(d.size()!=old)changed.push_back(v);}return true;
 }
 bool prop(Dom&D,vector<int>queue){vector<bool>in(g.fac.size());deque<int>q;sort(queue.begin(),queue.end(),[&](int x,int y){return g.fac[x].n>g.fac[y].n;});for(int f:queue)if(!in[f]){q.push_back(f);in[f]=true;}while(!q.empty()){int f=q.front();q.pop_front();in[f]=false;vector<int>changed;if(!factor(D,f,changed))return false;for(int v:changed)for(int z:g.vars[v].fac)if(z!=f&&!in[z]){in[z]=true;q.push_back(z);}}return true;}
 void dfs(Dom&D){if(sol.size()>=2||timeout||visits>=uint64_t(maxVisits)||timed())return;visits++;int v=-1;auto priority=[&](int i){if(mode==0)return double(D[i].size());if(mode==1)return log(double(D[i].size()))/g.vars[i].truth.size();if(mode==2)return log(double(D[i].size()))/max(size_t(1),g.vars[i].fac.size());return log(double(D[i].size()))/sqrt(double(g.vars[i].truth.size()));};for(int i=0;i<(int)D.size();i++)if(D[i].size()>1&&(v<0||priority(i)<priority(v)))v=i;if(v<0){sol.push_back(D);return;}for(int w:D[v]){if(sol.size()>=2||timeout||visits>=uint64_t(maxVisits)||timed())return;branches++;Dom E=D;E[v]={w};if(prop(E,g.vars[v].fac))dfs(E);}}
 void verify(Dom&D,int ix){array<vector<int>,3>P;for(int k=0;k<3;k++)for(auto s:g.sites[k])P[k].push_back(dec(g.vars[s.v].words[D[s.v][0]][s.i]));int id=0;for(int j=0;j<76;j++){int i=1;while(i<3&&P[i][j]==P[0][j])i++;int a=i==3?1:mod((g.c[i][j]-g.c[0][j])*inv[mod(P[i][j]-P[0][j])]),b=mod(g.c[0][j]-a*P[0][j]);if(!a)throw runtime_error("zero");for(int k=0;k<3;k++)if(mod(a*P[k][j]+b)!=g.c[k][j])throw runtime_error("replay");id+=i<3;}cout<<"SOLUTION identifiable "<<id<<endl;for(int k=0;k<3;k++){int correct=0;for(int j=0;j<76;j++){cout<<enc(P[k][j]);if(j==75||g.sites[k][j+1].v!=g.sites[k][j].v)cout<<' ';correct+=P[k][j]==g.plain[k][j];}cout<<" accuracy "<<(ix<2?correct:-1)<<endl;}}
 void run(int ix){Dom D;size_t init=0;for(auto&v:g.vars){vector<int>d(v.words.size());iota(d.begin(),d.end(),0);init+=d.size();D.push_back(move(d));}vector<int>queue(g.fac.size());iota(queue.begin(),queue.end(),0);bool ok=prop(D,queue);size_t root=0;int forced=0;for(auto&d:D){root+=d.size();forced+=d.size()==1;}cout<<"ROOT ok "<<ok<<" timeout "<<timeout<<" initial "<<init<<" remaining "<<root<<" forced "<<forced<<" vars "<<D.size()<<" pairs "<<pairs<<" factors "<<facCalls<<" contradiction "<<contradiction<<endl;if(ix<2&&ok){for(int i=0;i<(int)D.size();i++)if(none_of(D[i].begin(),D[i].end(),[&](int j){return g.vars[i].words[j]==g.vars[i].truth;}))throw runtime_error("lost true word");cout<<"TRUTH retained"<<endl;}if(ok){for(int i=0;i<(int)D.size();i++)cout<<i<<":"<<g.vars[i].track<<":"<<g.vars[i].idx<<":"<<D[i].size()<<" ";cout<<endl;dfs(D);}cout<<"SEARCH visits "<<visits<<" branches "<<branches<<" timeout "<<timeout<<" pairs "<<pairs<<" factorCalls "<<facCalls<<" solutions "<<sol.size()<<endl;for(auto&s:sol)verify(s,ix);}
};
int main(int argc,char**argv){for(int i=1;i<Q;i++)for(int j=1;j<Q;j++)if(i*j%Q==1)inv[i]=j;int N;cin>>N;for(int i=0;i<N;i++){string s;int f;cin>>s>>f;dict.push_back({s,f});}int n;cin>>n;string line;getline(cin,line);vector<array<vector<string>,3>> all;for(int i=0;i<n;i++){array<vector<string>,3>w;for(int k=0;k<3;k++){getline(cin,line);istringstream ss(line);string s;while(ss>>s)w[k].push_back(s);}all.push_back(w);}int ix=argc>1?atoi(argv[1]):0,ms=argc>2?atoi(argv[2]):10000,vis=argc>3?atoi(argv[3]):2000;auto g=make_graph(all.at(ix),ix);cout<<"case "<<ix<<" dictionary "<<N<<" factors "<<g.fac.size()<<endl;int mode=argc>4?atoi(argv[4]):0;Solver s{g,Clock::now(),ms,0,0,0,0,false,vis,mode};s.run(ix);}
